def find_pairs(grid):
    """Find all pairs of same-colored cells that are diagonally adjacent"""
    pairs = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 0:
                continue
            # Check all diagonal neighbors
            for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 10 and 0 <= nc < 19:
                    if grid[nr][nc] == grid[r][c]:
                        key = min(((r,c), (nr,nc)), ((nr,nc), (r,c)))
                        if key not in pairs:
                            pairs[key] = grid[r][c]
    return pairs

