def find_pairs(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    pairs = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                continue
            for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == grid[r][c]:
                        key = tuple(sorted([(r,c), (nr,nc)]))
                        if key not in pairs:
                            pairs[key] = grid[r][c]
    return pairs

